gTN(){return"\u062e\u0637 \u0627\u0644\u0645\u0633\u062a\u0646\u062f"},
gIc(){return"\u0644\u0648\u0646 \u062a\u0645\u064a\u064a\u0632 \u0627\u0644\u0645\u0633\u062a\u0646\u062f"},
